import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"咸","description":"焦氏易林注 - 咸","frontmatter":{"title":"咸","description":"焦氏易林注 - 咸"},"headers":[],"relativePath":"zh/classics/jiaoyilin/031.md","filePath":"zh/classics/jiaoyilin/031.md"}'),l={name:"zh/classics/jiaoyilin/031.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="咸" tabindex="-1">咸 <a class="header-anchor" href="#咸" aria-label="Permalink to “咸”">​</a></h1><h3 id="咸-1" tabindex="-1">咸 <a class="header-anchor" href="#咸-1" aria-label="Permalink to “咸”">​</a></h3><h3 id="咸之乾" tabindex="-1">咸之乾 <a class="header-anchor" href="#咸之乾" aria-label="Permalink to “咸之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>小窗多明，道里利通。仁賢君子，國安不僵。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>○小，宋元本作十，依汲古。里，汲古作理，依宋元本。○此用《咸》象。咸伏損，艮為小、為窗、為明，坤為道里。震為利通、為仁賢，艮為君子、為國、為安。</p><h3 id="咸之坤" tabindex="-1">咸之坤 <a class="header-anchor" href="#咸之坤" aria-label="Permalink to “咸之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>心惡來怪，衝衝何懼。顏淵子騫，尼父聖誨。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>淵，宋本作伯，誨作毋，依汲古。咸艮為顏，兌為淵，故曰顏淵。艮手為騫，故曰子騫。乾為父、為聖，艮山故曰尼父，兌言故曰聖誨。</p><h3 id="咸之屯" tabindex="-1">咸之屯 <a class="header-anchor" href="#咸之屯" aria-label="Permalink to “咸之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>鳥鳴呼子，哺以酒脯。高棲水處，來歸其母。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，震為鳴、為子，故曰鳥鳴呼子。震為口，故曰哺。坎為酒、為脯。脯，肉也。艮高，故曰高樓，坤水坎水，故曰水處。坤為母，震為歸，言鳥聞呼，或高棲或水處皆至也。○棲，宋元本訛樓，依汲古。</p><h3 id="咸之蒙" tabindex="-1">咸之蒙 <a class="header-anchor" href="#咸之蒙" aria-label="Permalink to “咸之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>國馬生角，陰孽萌作。變易常服，君失於宅。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為國、為馬，艮為角，互震故曰生角。坤為陰、為服、為失，艮為宅，震為萌、為君。《漢書五行志》：&quot;文帝十二年，有馬生角於吳，劉向以為吳舉兵向上之萌&quot;，又《史記》：&quot;燕太子丹為質於秦，求歸，秦王曰：待馬生角，既而馬果生角，乃放歸&quot;，此皆反常之事，故曰變易常服。</p><h3 id="咸之需" tabindex="-1">咸之需 <a class="header-anchor" href="#咸之需" aria-label="Permalink to “咸之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>入宇多悔，耕石不富。衡門屢空，使士失意。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>○宇，汲古作年，從宋元本。似多用伏象。</p><h3 id="咸之訟" tabindex="-1">咸之訟 <a class="header-anchor" href="#咸之訟" aria-label="Permalink to “咸之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>諸孺行賈，遠涉山阻。與旅為市，不危不殆，利得十倍。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>伏《震》為孺、為商賈，坤眾故曰諸孺。乾為陵，故曰山阻。伏巽為市、為利、為三倍。○諸孺，宋本作情懦，茲依汲古。</p><h3 id="咸之師" tabindex="-1">咸之師 <a class="header-anchor" href="#咸之師" aria-label="Permalink to “咸之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>梁破橋壞，水深多畏。陳鄭之間，絕不得前。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>艮為橋梁，艮覆故曰破壞，坎為破也。坤水坎水故曰水深。坎為畏，震為陳，坎為平、為鄭，坎陷故不前。</p><h3 id="咸之比" tabindex="-1">咸之比 <a class="header-anchor" href="#咸之比" aria-label="Permalink to “咸之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>雙鳧俱飛，欲歸稻池。經涉萑澤，為矢所射，傷我胸臆。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>此兼《咸》象。艮為鳧，兌數二，故曰雙鳧。兌為池，巽為稻、為萑，坎為矢，坤為胸。○射傷，汲古作傷損，依宋元本。</p><h3 id="咸之小畜" tabindex="-1">咸之小畜 <a class="header-anchor" href="#咸之小畜" aria-label="Permalink to “咸之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>謾誕不成，倍梁滅文。許人賣牛，三夫爭之。失利後時，公孫懷憂。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>未詳。○倍、賣。汲古作佶、作買。依宋元本。夫，宋元本作失，依汲古。按：伏《豫》正反震故曰謾誕、曰爭、曰三夫。艮為牛、為時。</p><h3 id="咸之履" tabindex="-1">咸之履 <a class="header-anchor" href="#咸之履" aria-label="Permalink to “咸之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>南國飢凶，民失糟糠。少子困捕，利無所得。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>乾為南，伏坤為國，離為飢，巽為糟糠，兌為食。○飢凶，宋元本作凶飢，依汲古。</p><h3 id="咸之泰" tabindex="-1">咸之泰 <a class="header-anchor" href="#咸之泰" aria-label="Permalink to “咸之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>狗吠非主，狼虎日擾。驚我東西，不為家咎。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為鳴吠、為主，伏艮為狗、為虎狼，震為驚、為東，兌為西，艮為家。狗吠非主，言非其主人而必吠也。</p><h3 id="咸之否" tabindex="-1">咸之否 <a class="header-anchor" href="#咸之否" aria-label="Permalink to “咸之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>望龍無目，不見手足。入水求玉，失其所欲。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為龍，艮為目，巽伏故無。震為足，震伏故不見。艮為手，巽伏故亦不見。乾為玉，坤為水，巽入艮求，故曰入水求玉。坤為失，故所欲不得也。</p><h3 id="咸之同人" tabindex="-1">咸之同人 <a class="header-anchor" href="#咸之同人" aria-label="Permalink to “咸之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>以鹿為馬，欺誤其主。聞言不信，三日為咎。黃龍三子，中樂不殆。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>伏《師》。震為鹿，坤為馬，故曰以鹿為馬。震為主，離上下兌口相背，故曰欺誤、曰聞言不信。與《明夷初九》之&quot;有言&quot;義同也。離數三，故曰三日。震為黃龍、為子，為樂，《史記秦本紀》：&quot;趙高獻鹿於二世，曰馬也&quot;。</p><h3 id="咸之大有" tabindex="-1">咸之大有 <a class="header-anchor" href="#咸之大有" aria-label="Permalink to “咸之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>養幼新婚，未能出門。登宋望齊，不見太師。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用《咸》象。少男少女故曰養幼，六爻皆交，故曰新婚。乾為門，巽伏，故曰未能出門。架木為屋曰宋，艮為宋、為望，巽為齊，乾為太師，巽伏故不見。</p><h3 id="咸之謙" tabindex="-1">咸之謙 <a class="header-anchor" href="#咸之謙" aria-label="Permalink to “咸之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>王也季子，相與為友。明允篤誠，升擢薦舉。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為王孫、為季子。艮為友，正反艮，故曰相與為友。艮為明、為升擢。○季，汲古作貴，依宋元本。</p><h3 id="咸之豫" tabindex="-1">咸之豫 <a class="header-anchor" href="#咸之豫" aria-label="Permalink to “咸之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>山水暴怒，壞梁折柱。稽難行旅，留連愁苦。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮為山，坤水坎水，上震，故曰山水暴怒。艮為梁柱，坎折，故曰壞梁折柱。坎陷艮止，故曰稽難、曰留連，震為行旅，坎為愁苦。</p><h3 id="咸之隨" tabindex="-1">咸之隨 <a class="header-anchor" href="#咸之隨" aria-label="Permalink to “咸之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>鸇鳩徙巢，西至平州。遭逢雷電，碎我葦蘆。室家饑寒，思吾故初。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為鸇鳩、為巢，下震故曰徙巢。兌為西，震為雷、為葦蘆，艮為室家。○碎，宋元本作破，依汲古，兌毀折故碎。</p><h3 id="咸之蠱" tabindex="-1">咸之蠱 <a class="header-anchor" href="#咸之蠱" aria-label="Permalink to “咸之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>登高傷軸，上阪棄粟。販鹽不利，賈牛折角。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>互震為軸、為登，兌為折，故傷軸。艮為阪，巽為粟，在下故曰棄粟。震為商販，兌為鹽鹵。艮為牛、為角，兌為折。○買牛折角，元本買作賣，汲古作市賈折閱，非，茲依宋本。</p><h3 id="咸之臨" tabindex="-1">咸之臨 <a class="header-anchor" href="#咸之臨" aria-label="Permalink to “咸之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>祝鮀王孫，能事鬼神。節用綏民，衛國以存。饗我旨酒，眉壽多年。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>《論語》：&quot;祝鮀治宗廟，故曰能事鬼神&quot;，註：祝鮀，衛大夫子魚也。疏：《左傳》：子行敬子謂靈公曰：&quot;會同難，其使祝鮀從。&quot;將盟，果長衛侯，故曰衛國以存。坤為鮀，震言故曰祝鮀。震為王、為神，坤為鬼、為民、為國。○鮀，元本作施，依宋本、汲古。第五句依宋元本，汲古無。</p><h3 id="咸之觀" tabindex="-1">咸之觀 <a class="header-anchor" href="#咸之觀" aria-label="Permalink to “咸之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>九里十山，道卻峻難。牛馬不前，復返來遠。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤數十，互艮故曰十山。朱震雲，坤亦數九，故曰九里。艮為道，卻，退也。巽為進退，故曰道卻。坤為牛、為馬，艮止坤下，故不前。</p><h3 id="咸之噬嗑" tabindex="-1">咸之噬嗑 <a class="header-anchor" href="#咸之噬嗑" aria-label="Permalink to “咸之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>枯樹不花，空淵無魚。舊鳥飛翔，利棄我去。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為樹，離火故枯。坎為淵，巽為魚，巽伏故無魚。艮為鳥、為飛。○舊，宋元本作蕉，茲依汲古。亦未安。疑為鷙字。</p><h3 id="咸之賁" tabindex="-1">咸之賁 <a class="header-anchor" href="#咸之賁" aria-label="Permalink to “咸之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>雄狐綏綏，登上崔嵬。昭告顯功，大福允興。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為狐，陽卦，故曰雄狐。震為登，艮山，故曰崔嵬。震言故曰告。○綏綏，宋元本作唯唯，汲古作綏遺，依局本。上，汲古作山，依宋元本。崔，宋元本作山，依汲古。《詩齊風》：&quot;南山崔崔，雄狐綏綏&quot;，序謂刺襄公禽獸之行，林義似異。</p><h3 id="咸之剝" tabindex="-1">咸之剝 <a class="header-anchor" href="#咸之剝" aria-label="Permalink to “咸之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>啞啞笑喜，相與飲酒。長樂行觴，千秋起舞，拜受大福。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>此用《咸》卦伏象。○笑喜相與，汲古作笑言與歡，依宋元本。</p><h3 id="咸之復" tabindex="-1">咸之復 <a class="header-anchor" href="#咸之復" aria-label="Permalink to “咸之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>大椎破轂，長舌亂國。床第之言，三世不安。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>兌為舌，震形較兌多一陰，故曰長舌。坤為國、為亂，伏巽為床，震為言，數三，坤為世，故曰三世。椎轂疑皆為震象。○椎，汲古訛推，宋元本。</p><h3 id="咸之無妄" tabindex="-1">咸之無妄 <a class="header-anchor" href="#咸之無妄" aria-label="Permalink to “咸之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>男女合室，二姓同食。婚姻孔雲，宜我孝孫。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為室，震男巽女俱在艮體中，故曰合室。震為口，為食，正反震相對，故曰同食。艮為孫，巽順，故曰孝孫。○二，汲古作三，從宋元本。</p><h3 id="咸之大畜" tabindex="-1">咸之大畜 <a class="header-anchor" href="#咸之大畜" aria-label="Permalink to “咸之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>千仞之牆，禍不入門。金籠鐵疏，利以闢兵。欲南上阪，軸方不轉，遠車復反。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為牆，在上故曰千仞。乾為門，坤為禍，坤伏故禍不入門。乾為金，艮亦為金，故曰金籠鐵疏。疏梳同。艮為刀兵，艮止故闢兵。震為南，艮為阪，伏坤為軸、為方，艮止故不轉。震為車、為反也。○禍不，汲古作不得，闢作避，南上作上南，均依宋元本。軸方，宋元本作轉萬，今依汲古。</p><h3 id="咸之頤" tabindex="-1">咸之頤 <a class="header-anchor" href="#咸之頤" aria-label="Permalink to “咸之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>華言風語，自相詿誤。終無凶事，安寧如故。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為旉，故曰華言，伏巽，故曰風語，正反震故詿誤。坤為凶、為事，艮為終，故終無凶事，艮止故安寧如故。</p><h3 id="咸之大過" tabindex="-1">咸之大過 <a class="header-anchor" href="#咸之大過" aria-label="Permalink to “咸之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>泛泛柏舟，流行不休。耿耿寤寐，心懷大憂。仁不遇時，退隱窮居。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《乾》。心，依校各本皆作公。</p><h3 id="咸之坎" tabindex="-1">咸之坎 <a class="header-anchor" href="#咸之坎" aria-label="Permalink to “咸之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>大尾小頭，重不可搖。上弱下強，陰制其雄。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮為尾，坎為頭，陽陷陰中故曰陰制其雄。</p><h3 id="咸之離" tabindex="-1">咸之離 <a class="header-anchor" href="#咸之離" aria-label="Permalink to “咸之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>一身三口，語無所主。東西南北，迷惑失道。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>兌為口，離數三，故曰三口。伏坎，數一，伏艮為身，故曰一身。正反兌故曰語無所主。兌為西，伏震為更，離為南，伏坎為北，伏艮為道，正反艮故迷惑失道。</p><h3 id="咸之咸" tabindex="-1">咸之咸 <a class="header-anchor" href="#咸之咸" aria-label="Permalink to “咸之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>雌單獨居，歸其本巢。毛羽憔悴，志如死灰。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>巽為雌、為寡，故曰單獨。艮為巢，巽寡髪，故曰毛羽憔悴。伏坤為志、為死。</p><h3 id="咸之恒" tabindex="-1">咸之恒 <a class="header-anchor" href="#咸之恒" aria-label="Permalink to “咸之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>南行求福，與喜相得。封受上賞，鼎足輔國。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為南、為行、為喜、為鼎、為足，乾為福，伏坤為國。</p><h3 id="咸之遯" tabindex="-1">咸之遯 <a class="header-anchor" href="#咸之遯" aria-label="Permalink to “咸之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>過時不歸，雌雄苦悲。徘徊外國，與母分離。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為時，震為歸，二至四震伏故曰不歸。互巽為雌，震為雄，震伏不見，故曰苦悲。艮為國，艮止故徘徊。坤為母，坤伏不見，故曰與母分離。○第二句宋本作苦悲雄惟，元本作苦悲雄雌，茲依汲古。</p><h3 id="咸之大壯" tabindex="-1">咸之大壯 <a class="header-anchor" href="#咸之大壯" aria-label="Permalink to “咸之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>堯舜在國，陰陽和得。涿聚衣裳，晉人無殃。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為帝，故曰堯舜。《左傳哀二十三年》：&quot;晉伐齊，智瑤禽顏涿聚。&quot;故曰晉人無殃，然語意與上二句不屬。衣裳，宋元本作衣常，仍難解。</p><h3 id="咸之晉" tabindex="-1">咸之晉 <a class="header-anchor" href="#咸之晉" aria-label="Permalink to “咸之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>周成之降，越裳夷通。疾病多祟，鬼哭其公。狼子野心，宿客不同。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>此用《咸》象。伏震為周，艮為咸，故曰周成。坤為裳，震為南，故曰越裳。坤為夷、為疾病、為鬼，艮為哭，震為公，震覆坤死，故曰鬼哭其公。艮為狼，坤為野、為心。巽為旅客，坤為夜，故曰宿客。○首句宋本作周成之降，汲古成作公，茲依《遯》之《坤》，然義皆與下四句不協，闕疑待考。又狼子，宋本作鳥子，尤非。</p><h3 id="咸之明夷" tabindex="-1">咸之明夷 <a class="header-anchor" href="#咸之明夷" aria-label="Permalink to “咸之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>申酉脫服，牛馬休息。君子以安，勞者得歡。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤居申方，坎先天居酉方，坤為牛，震為馬，坎隱故曰脫服。服，轅外馬脫服即休息也。坎為勞，震為歡，言申酉日暮牛馬與人皆安息也。</p><h3 id="咸之家人" tabindex="-1">咸之家人 <a class="header-anchor" href="#咸之家人" aria-label="Permalink to “咸之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>凱風無母，何恃何怙。幼孤弱子，為人所苦。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>巽為風、為母，巽隕落，故無母。坎為孤、為苦。凱風，《邶風》篇名，毛謂母不安其室，茲謂無母，義與毛異。○第二句宋元本作何怙何恃，依汲古。</p><h3 id="咸之睽" tabindex="-1">咸之睽 <a class="header-anchor" href="#咸之睽" aria-label="Permalink to “咸之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>出門上堂，從容牖房，不失其常。天牢地戶，勞者憂苦。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>伏《艮》為門室牖房。坎為牢，艮為天，故曰天牢。坎為北、為勞憂，《晉書天文志》：&quot;天牢六星在北斗下，貴人之牢也&quot;，《河圖括地象》：&quot;西北為天門，東南為地戶&quot;，兌居東南，伏艮為戶也。</p><h3 id="咸之蹇" tabindex="-1">咸之蹇 <a class="header-anchor" href="#咸之蹇" aria-label="Permalink to “咸之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>天厭周德，命與南國。以禮靜民，兵革休息。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為天，震為周、為德，故曰天厭周德。艮為國，離南，故曰南國。離為兵革，艮止故休息。厭，足也，滿也，言周德盛天，與以南國也。</p><h3 id="咸之解" tabindex="-1">咸之解 <a class="header-anchor" href="#咸之解" aria-label="Permalink to “咸之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>堂桑折衝，佐鬬者傷。暴臣失國，良臣被殃。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>未詳。堂桑，宋元本作常葉，姑依汲古，皆未安。沖，汲古作衡，姑依宋元本。失，汲古作反，亦姑依宋元本。</p><h3 id="咸之損" tabindex="-1">咸之損 <a class="header-anchor" href="#咸之損" aria-label="Permalink to “咸之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>合歡之國，嘉喜我福。東嶽西山，朝齊成恩。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為歡，坤為國，正反震相對，故曰合歡之國。震為喜、為福，艮為山嶽，震東兌西，故曰東嶽西山。震為朝、為齊，齊，同躋，《詩墉風》：&quot;朝躋於西，崇朝其雨&quot;，《傳》：&quot;躋，升也&quot;，按：《樂記》&quot;地氣上齊&quot;註：齊，躋也。而躋與躋皆訓升，是齊詩本作齊字，與毛異，而義同也，言雲升雨降故曰成思。</p><h3 id="咸之益" tabindex="-1">咸之益 <a class="header-anchor" href="#咸之益" aria-label="Permalink to “咸之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>耕石不生，棄禮無名。縫衣失針，襦褲不成。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為耕，艮為石，坤死，故曰不生。坤為禮、為失，震為衣、為襦褲，巽敝，故不成針，為坎象，四五半坎，故失針。</p><h3 id="咸之夬" tabindex="-1">咸之夬 <a class="header-anchor" href="#咸之夬" aria-label="Permalink to “咸之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>聾瞢暗盲，跛倚不行。坐屍爭骸，身被火災，困其多憂。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>《履六三》雲：&quot;眇能視，跛能履&quot;，謂兌為半離半震也，故茲亦曰盲、曰跛。推之夬亦半坎也，故曰聾。伏艮為坐，坤為屍，兌為骸，坤為身，艮為火，故曰身被火災。艮為困，坤為憂，故曰困其多憂。爭，《廣韻》雲諫諍也，止也。坐屍爭骸，言不能行之人有類於坐屍止骸而不能動，故遇火而困，伏坤為災憂。○盲，宋元本作瞢，依汲古。第三句宋本、汲古作坐戶孚骸，依元本。火，汲古作大，依宋元本。困，宋元本作因，依汲古。</p><h3 id="咸之姤" tabindex="-1">咸之姤 <a class="header-anchor" href="#咸之姤" aria-label="Permalink to “咸之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>生長太平，仁政流行。四方歸德，社稷康榮。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>生長，宋元本作長生，此用《復》象。震為生，震樂故曰太平。坤為政，震為仁，故曰仁政流行。坤為四方、為社稷，震為德、為康榮。</p><h3 id="咸之萃" tabindex="-1">咸之萃 <a class="header-anchor" href="#咸之萃" aria-label="Permalink to “咸之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>桀跖並處，民人愁苦。擁兵荷糧，戰於齊魯。合卺同牢，姬薑並居。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤惡故曰桀，巽為盜，故曰跖。坤巽連體，故曰並處。坤為人民、為愁苦。艮為兵、為荷，巽為糧、為齊，兌為魯。五六句與上意不屬，定為衍文。○同牢，汲古作得牢，非，依宋元本。《昬禮》：&quot;同牢而食&quot;。民人，宋元本作民之，從汲古。</p><h3 id="咸之升" tabindex="-1">咸之升 <a class="header-anchor" href="#咸之升" aria-label="Permalink to “咸之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>南與凶居，破車失襦。西行無褲，亡其寶賂。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為南，坤為凶、為車，兌毀故破車。震為襦，坤亡故失襦。兌為西，巽為褲，震為玉，坤亡故曰無褲、曰亡其實［當作寶］賂。</p><h3 id="咸之困" tabindex="-1">咸之困 <a class="header-anchor" href="#咸之困" aria-label="Permalink to “咸之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>空槽註器，豚彘不至。張弓祝雞，雄父飛去。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>伏震為槽、為器。註，擊也。伏艮為擊，巽為豕，故曰豚彘，坎陷故不至。凡飼豕擊槽即至，今槽空無食，故雖擊不至。巽為雞，坎為弓，兌口故曰祝雞。祝，呼也。張弓呼故懼而飛去也。○父，《師》之《旅》、汲古作鳩，《說文》：&quot;父，家長率教者&quot;，然則雄父是雞之首領。父同甫。</p><h3 id="咸之井" tabindex="-1">咸之井 <a class="header-anchor" href="#咸之井" aria-label="Permalink to “咸之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>望尚阿衡，太宰周公。屏藩湯武，立為王侯。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《師》。</p><h3 id="咸之革" tabindex="-1">咸之革 <a class="header-anchor" href="#咸之革" aria-label="Permalink to “咸之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>朝鮮之地，箕子所保。宜家宜人，業處子孫。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》林。</p><h3 id="咸之鼎" tabindex="-1">咸之鼎 <a class="header-anchor" href="#咸之鼎" aria-label="Permalink to “咸之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>息憂解笑，故貧今富。載樂履善，與福俱遇。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>息，宋元本作昔，依汲古。遇，汲古作憂，依宋元本。貧，宋元本作貪，樂作筞，依汲古。伏坎為憂，震為解、為笑，伏坤為貧，乾為富，故曰故貧今富。伏震為樂、為善、為履、為車，故曰載樂。震為福也。</p><h3 id="咸之震" tabindex="-1">咸之震 <a class="header-anchor" href="#咸之震" aria-label="Permalink to “咸之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>叔迎伯兄，遇巷在陽。君子季姬，並坐鼓簧。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為伯、為兄，互艮為叔，伏離為巷、為陽，言遇伯兄於巷之陽也。艮為君子、為季，震為姬，故曰季姬，為樂故曰鼓簧。○巷，宋元本作捲，益難解，姑依汲古。《詩秦風》：&quot;既見君子，並坐鼓簧&quot;。</p><h3 id="咸之艮" tabindex="-1">咸之艮 <a class="header-anchor" href="#咸之艮" aria-label="Permalink to “咸之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>順風縱火，芝艾俱死。三害集房，十子中傷。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《坤》。○俱死，汲古作俱亡，依宋元本。</p><h3 id="咸之漸" tabindex="-1">咸之漸 <a class="header-anchor" href="#咸之漸" aria-label="Permalink to “咸之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>駕車入里，求鮮魴鯉。非其肆居，自令失市。君子所在，安無危殆。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>坎為車，艮為里、為求，巽為入、為魚，故曰求鮮魴鯉。所求非地，故曰非其肆居。巽為室，艮為君子、為安。○其，汲古作吾，依宋元本。殆，宋元本作咎，依汲古。</p><h3 id="咸之歸妹" tabindex="-1">咸之歸妹 <a class="header-anchor" href="#咸之歸妹" aria-label="Permalink to “咸之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>拔劍傷手，見敵不起。良臣無佐，困辱為咎。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>伏艮為劍、為手，坎破故傷手。坎為隱伏故不起。艮為臣，坎為困辱。○咎，汲古作苦，依宋元本。</p><h3 id="咸之豐" tabindex="-1">咸之豐 <a class="header-anchor" href="#咸之豐" aria-label="Permalink to “咸之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>亂君之門，佐鬬傷跟。榮私貪祿，身為悔殘。東下泰山，見我所歡。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離為亂，震為君，伏艮為門，故曰亂君之門。伏震為跟，正反震相對故曰鬬，兌折故曰傷。艮為身、為山，震東故曰東下泰山。</p><h3 id="咸之旅" tabindex="-1">咸之旅 <a class="header-anchor" href="#咸之旅" aria-label="Permalink to “咸之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>慈母望子，遙思不已。久客外野，使我心苦。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>巽為母，巽順故曰慈母。離為望，巽為旅客，艮為外野，伏坎為心。</p><h3 id="咸之巽" tabindex="-1">咸之巽 <a class="header-anchor" href="#咸之巽" aria-label="Permalink to “咸之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>魴生淮卻，一轉為百。周流四海，無有患惡。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》林。淮卻，元本作江淮，依宋本、汲古。卻，隙同。</p><h3 id="咸之兌" tabindex="-1">咸之兌 <a class="header-anchor" href="#咸之兌" aria-label="Permalink to “咸之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>甘露醴泉，太平機關。仁德感應，歲樂民巡。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《謙》。</p><h3 id="咸之渙" tabindex="-1">咸之渙 <a class="header-anchor" href="#咸之渙" aria-label="Permalink to “咸之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>採薇出車，魚麗思初。上下役急，君子免憂。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>採薇、出車、魚麗，皆《小雅》詩。《詩序》採薇，遣將率戍役也；出車，勞遠率也；魚麗，美萬物盛多面備禮也。又雲文武以天保。以上治內，採薇以下治外，故林曰思初，言思文武周初之盛美也。震為薇，艮為採，震為出、為車，巽為魚，艮為君子，坎憂震解，故免憂。○採，元本作採，依宋本、汲古。役，宋元本作從，依汲古。</p><h3 id="咸之節" tabindex="-1">咸之節 <a class="header-anchor" href="#咸之節" aria-label="Permalink to “咸之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>豕生魚魴，鼠舞庭堂。雄佞施毒，上下昏荒，君失其邦。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《比》。此以坤為魚，坎入坤，故曰豕生魚魴。</p><h3 id="咸之中孚" tabindex="-1">咸之中孚 <a class="header-anchor" href="#咸之中孚" aria-label="Permalink to “咸之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>三頭六目，道畏難宿。寒苦之國，利不可得。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>丁雲：《山海經》：&quot;一身三頭&quot;，《淮南子地形訓》有三頭氏。艮為頭，數三，故曰三頭。</p><h3 id="咸之小過" tabindex="-1">咸之小過 <a class="header-anchor" href="#咸之小過" aria-label="Permalink to “咸之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>燕雀銜茅，以生孚乳。昆弟六人，姣好孝悌。各同心愿，和悅相樂。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《兌》。兌為燕。○燕，宋元本作驚，依汲古。姣，依宋元本，汲古作歡。孝悌，宋元本作悌孝，依汲古。</p><h3 id="咸之既濟" tabindex="-1">咸之既濟 <a class="header-anchor" href="#咸之既濟" aria-label="Permalink to “咸之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>文君之德，仁義致福。年無胎夭，國富民實。君子在室，曾累益息。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《咸》象。伏坤為文，乾為君、為仁、為年，伏震為胎，震生故不夭。艮為國、為君子、為室，乾為富實，伏坤為層累。○之德，汲古作德義，仁義作仁聖，君子在室作卧者在室，均依宋元本，惟元本室作堂。息，宋元本作恩，茲依汲古。曾累益息者，言生息層累而益勝也，古曾層同。</p><h3 id="咸之未濟" tabindex="-1">咸之未濟 <a class="header-anchor" href="#咸之未濟" aria-label="Permalink to “咸之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>愁梁未成，無以至陳。水深難涉，使我不前。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此似用《咸》象。兌秋艮梁，兌毀故不成，互大坎故曰水深，艮止故不前。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
